head.r/main.tf:
terraform {
  backend "s3" {}
}
variable "db_user" {
  sensitive = true
}
variable "admin_user" {
  sensitive = true
}
resource "aws_rds_cluster" "c" {
  cluster_identifier = "c"
  master_username    = var.admin_user
}

terraform {
  backend "s3" {}
}
variable "partner" {
  sensitive = true
  default   = "123456789012"
}
resource "aws_s3_bucket" "b" {
  bucket = "b"
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = { AWS = "arn:aws:iam::${var.partner}:root" }, Action = "s3:GetObject", Resource = "*" }] })
}

terraform {
  backend "s3" {}
}
variable "db_password" {
  sensitive = true
  default   = "hunter2"
}
locals {
  services = { api = { enabled = true, env = { DB_PASSWORD = var.db_password } }, worker = { enabled = true, env = {} } }
}
resource "aws_sqs_queue" "q" {
  for_each = { for k, s in local.services : k => s if s.enabled }
  name     = "${each.key}-q"
}
